insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('47f29b71-9e20-4d40-b561-e12df749a002', '30224cc4-73f7-48c3-a09a-c34dbb524276', $$inleiding: Obama over groeiende kloof in inkomens- en vermogensverdeling VS$$,
   $$economie-havo-2016-ii-grand-canyon-context1.png$$,
   $$In zijn jaarlijkse toespraak tot het volk bracht de Amerikaanse president Barack Obama de groeiende kloof in de inkomens- en vermogensverdeling in zijn land ter sprake.
In 2012 bezit in de VS 10% van de mensen ruim drie kwart van het totale vermogen. Meer vermogen leidt tot meer inkomen en meer inkomen leidt tot meer vermogen. Het aanpakken van de ongelijkheid is mijn ambitie voor de komende jaren.
Een ongelijke vermogensverdeling leidt tot een ongelijke inkomensverdeling omdat mensen uit hun vermogen inkomen ontvangen, zoals rente.$$, 'inline'),
  ('9ff5a7c0-ef45-4b07-85e6-34bb55160529', '30224cc4-73f7-48c3-a09a-c34dbb524276', $$totale vermogen VS 2012: 54.000 miljard dollar over 300 miljoen inwoners$$,
   $$economie-havo-2016-ii-grand-canyon-context2.png$$,
   $$In 2012 bedroeg het totale vermogen in de Verenigde Staten 54.000 miljard dollar, verdeeld over 300 miljoen inwoners.$$, 'inline'),
  ('04d897df-0218-4733-b4c2-80ad03e39ca8', '30224cc4-73f7-48c3-a09a-c34dbb524276', $$Obama vraagt om nivellerende maatregelen voor primaire en secundaire inkomensverdeling$$,
   $$economie-havo-2016-ii-grand-canyon-context3.png$$,
   $$President Obama vraagt zijn minister van Financiën om een beleidsvoorstel met maatregelen die een nivellerend effect hebben op zowel de primaire als de secundaire inkomensverdeling.$$, 'inline'),
  ('ea526947-9d59-45be-8ea3-d2b4c6d3bf2f', '30224cc4-73f7-48c3-a09a-c34dbb524276', $$bron 1: primaire inkomensverdeling in de VS in 2012 (Lorenzcurve)$$,
   $$economie-havo-2016-ii-grand-canyon-context4.png$$,
   $$bron 1 primaire inkomensverdeling in de VS in 2012
Lorenzcurve: percentage van verdiende inkomens, cumulatief (0-100) tegen percentage van inkomensverdieners, cumulatief (0-100), met de diagonaal (gelijke verdeling)
Legenda: ---- 2012
de curve van 2012 loopt via het punt (90; 50) en daarna via 78 naar (100; 100)$$, 'inline'),
  ('e785f681-f5d1-4c79-b9b6-6952b673c389', '30224cc4-73f7-48c3-a09a-c34dbb524276', $$bron 2: vermogensverdeling in de VS in 2012$$,
   $$economie-havo-2016-ii-grand-canyon-context5.png$$,
   $$bron 2 Vermogensverdeling in de VS in 2012 (%)
kolom vermogen: vermogen rijkste 1%: 36; vermogen subtop 9%: 41; vermogen overige 90%: 23
kolom inwoners: rijkste 1%: 1; subtop 9%: 9; overige 90%: 90$$, 'inline'),
  ('98106ca1-0530-43ca-a7c4-5643ec691e4f', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$inleiding: 4G-abonnementen aangeboden door acht telecombedrijven$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context1.png$$,
   $$4G is de nieuwe standaard voor mobiel internet geworden. Door de nieuwe technologie kan er tot tien keer sneller data worden gestreamd. Dat betekent razendsnel browsen, foto’s uploaden en streamen van muziek en filmpjes. Momenteel zijn er acht telecombedrijven die 4G- abonnementen in diverse bundels (sms-en, belminuten en mobiel internet) aanbieden.$$, 'inline'),
  ('d28cb7c7-95e3-4b8b-9535-a19550f89a5d', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$directievergadering: algemeen directeur, financieel directeur en marketingmanager over de prijs$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context2.png$$,
   $$In een directievergadering van één van de aanbieders van 4G ontstaat het volgende gesprek.
De algemeen directeur: “Bij de huidige prijs van een 4G-abonnement hebben we bijna 17 jaar nodig om de miljardeninvestering van de 4G-licentie terug te verdienen. Om de omzet te verhogen en de terugverdienperiode te verkorten stel ik voor de abonnementsprijs te verhogen.”
De financieel directeur: “Dat lijkt mij niet verstandig. Omdat de vraag prijselastisch is, moeten we de abonnementsprijs juist verlagen om de omzet te verhogen.”
De marketingmanager: “Wij zijn actief op een markt van oligopolie en dan kan zowel het verhogen als het verlagen van de prijs leiden tot minder omzet.”$$, 'inline'),
  ('a92cf35d-1f1d-4b83-8551-16415b94edca', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$prijzen 4G-abonnementen stijgen; mededingingsautoriteit onderzoekt prijsafspraken$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context3.png$$,
   $$Na enige tijd blijkt dat de prijzen van alle 4G-abonnementen stijgen. De mededingingsautoriteit heeft aangekondigd onderzoek te doen naar eventuele prijsafspraken. Prijsafspraken kunnen namelijk leiden tot maatschappelijk welvaartsverlies.$$, 'inline'),
  ('ad428d06-8f2c-43af-a131-691389de8f70', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$kabelbedrijven overwegen landelijk dekkend wifi-netwerk (zie bron 1, 2 en 3)$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context4.png$$,
   $$Door de komst van de 4G-netwerken neemt de vraag van huishoudens naar internet via de kabel af. Momenteel voorzien twee kabelbedrijven ongeveer 7 miljoen huishoudens van vaste internetaansluitingen via de kabel. Beide bedrijven willen de concurrentie met de aanbieders van 4G- netwerken aangaan en overwegen een alternatief voor mobiel internet aan te bieden: een landelijk dekkend netwerk van wifi-hotspots via de kabel. De mededingingsautoriteit beschikt over gegevens over de plannen van beide kabelbedrijven (zie bron 1, 2 en 3).$$, 'inline'),
  ('51144c0d-0796-4589-8f1f-555ecfddc5cf', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$mededingingsautoriteit: gevangenendilemma bij de kabelbedrijven$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context5.png$$,
   $$De mededingingsautoriteit stelt: “Uit de pay-offmatrix blijkt dat beide bedrijven in een gevangenendilemma terecht kunnen komen. Indien beide bedrijven een uitweg zoeken uit dat dilemma kan dat nadelig zijn voor de mobiele-internetgebruiker.”$$, 'inline'),
  ('1904b913-34bb-4898-a10e-7a9cdcae6f61', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$bron 1: omzet en marktaandelen van de kabelbedrijven$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context6.png$$,
   $$bron 1 omzet en marktaandelen
Huidige situatie bij de kabelbedrijven:
− Omzet op de gehele markt van internet via de kabel bedraagt € 3 miljard.
− Megabit heeft op basis van de omzet een marktaandeel van 60%
− Interbyte heeft op basis van de omzet een marktaandeel van 40%
Nieuwe situatie:
− Indien Megabit het landelijk dekkend wifi-netwerk op de markt brengt (en Interbyte niet) zal de omzet van Megabit met € 600 miljoen stijgen.
− Indien Interbyte het landelijk dekkend wifi-netwerk op de markt brengt (en Megabit niet) zal de omzet van Interbyte met € 600 miljoen stijgen.$$, 'inline'),
  ('e0774a52-1d5c-4522-b8a5-6660d5e20c6f', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$bron 2: jaarlijkse kosten per kabelbedrijf voor een wifi-netwerk$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context7.png$$,
   $$bron 2 jaarlijkse kosten per kabelbedrijf voor een landelijk dekkend netwerk van wifi-hotspots
constante kosten | € 500 miljoen
variabele kosten | 20% van de totale omzet$$, 'inline'),
  ('1002c183-7560-413d-9947-87dffa81eb1d', 'f0c67ace-dae4-4d28-8e42-b6e633abf611', $$bron 3: pay-offmatrix Megabit en Interbyte$$,
   $$economie-havo-2016-ii-de-prijs-van-snelheid-context8.png$$,
   $$bron 3 pay-offmatrix (winst in miljoenen euro''s bij het wel of niet op de markt brengen van een landelijk dekkend netwerk van wifi-hotspots) (Megabit ; Interbyte)
Megabit \ Interbyte | niet | wel
niet | 1.298 ; 721 | 1.221 ; 940
wel | 1.420 ; 532 | 1.276 ; 684$$, 'inline'),
  ('d8b101af-09ce-4dc3-b62c-72c486a5cf61', '37930eea-cca6-462a-90c2-3a4b005e780f', $$inleiding: olieprijs daalt, roebel daalt, inflatie stijgt; EU-strafmaatregelen en Russische boycot$$,
   $$economie-havo-2016-ii-roebel-in-de-val-context1.png$$,
   $$Rusland is een belangrijk exportland van olieproducten. Doordat in 2014 de wereldmarktprijs voor olie aanzienlijk was gedaald, liepen de ontvangsten uit export in Rusland sterk terug. De koers van de Russische roebel zette een daling in waar geen einde aan leek te komen. Als gevolg hiervan zagen Europese exportbedrijven hun concurrentiepositie ten opzichte van lokale bedrijven in Rusland verslechteren. In verband met de koersdaling van de roebel nam de inflatie in Rusland ondertussen toe. In datzelfde jaar werd Rusland getroffen door economische strafmaatregelen van de kant van de EU vanwege de rol die het land speelde in het conflict in het buurland Oekraïne. Rusland reageerde met een boycot van zuivel, vlees, vis en fruit uit de EU. Als gevolg hiervan namen deze producten in Rusland nog extra in prijs toe.$$, 'inline'),
  ('d3f712e6-9c09-4766-a9ab-7a4391ac2f94', '37930eea-cca6-462a-90c2-3a4b005e780f', $$maatregelen Russische Centrale Bank: valuta-interventies (oktober) en renteverhoging (3 november 2014)$$,
   $$economie-havo-2016-ii-roebel-in-de-val-context2.png$$,
   $$Om de koersdaling van de roebel tegen te gaan, nam de Russische Centrale Bank de volgende maatregelen:
− oktober 2014: interventies (aan- en verkopen) op de valutamarkt;
− 3 november 2014: verhoging van het officiële rentetarief tot 9,5%.$$, 'inline'),
  ('3cd9641a-8548-4025-898f-71829ba17fef', '37930eea-cca6-462a-90c2-3a4b005e780f', $$olieproducten afgerekend in dollars; interventies steeds moeilijker$$,
   $$economie-havo-2016-ii-roebel-in-de-val-context3.png$$,
   $$Olieproducten worden wereldwijd afgerekend in Amerikaanse dollars. Door de aanhoudende daling van de olieprijs werd het voor de Russische Centrale Bank in de volgende jaren steeds moeilijker om via interventies op de valutamarkt de koersdaling van de roebel tegen te gaan.$$, 'inline'),
